def Xform "Asset"
{
    def Mesh "Geo" (
        prepend apiSchemas = ["MaterialBindingAPI"]
    )
    {
        int[] faceVertexCounts = [3]
        int[] faceVertexIndices = [0, 1, 2]
        rel material:binding = </Asset/Looks/VertexColor>
        point3f[] points = [(0, 0, 0), (1, 0, 0), (0, 1, 0)]
        color3f[] primvars:displayColor = [(1, 0, 0), (0, 1, 0), (0, 0, 1)] (
            interpolation = "vertex"
        )
    }

    def Scope "Looks"
    {
        def Material "VertexColor"
        {
            token outputs:surface.connect = </Asset/Looks/VertexColor/Surface.outputs:surface>

            def Shader "Surface"
            {
                uniform token info:id = "UsdPreviewSurface"
                color3f inputs:diffuseColor.connect = </Asset/Looks/VertexColor/ColorReader.outputs:result>
                token outputs:surface
            }

            def Shader "ColorReader"
            {
                uniform token info:id = "UsdPrimvarReader_float3"
                string inputs:varname = "displayColor"
                float3 outputs:result
            }
        }
    }
}

